import { useState, FormEvent } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton, JxAlert } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function InviteTeamMemberForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const emailTouched = email.length > 0;
  const emailValid = EMAIL_PATTERN.test(email);
  const canSubmit = emailValid && role.length > 0;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canSubmit) return;
    setSubmitted(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px', maxWidth: '420px' }}>
      {submitted && (
        <JxAlert intent="success" title="Приглашение отправлено" onClose={() => setSubmitted(false)}>
          Мы отправили приглашение на адрес {email}.
        </JxAlert>
      )}
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          helperText="Мы отправим ссылку-приглашение на этот адрес"
          errorText={emailTouched && !emailValid ? 'Похоже, это не адрес электронной почты' : undefined}
        />
        <JxSelect
          label="Роль"
          placeholder="Выберите роль"
          options={[
            { value: 'member', label: 'Участник' },
            { value: 'admin', label: 'Администратор' },
            { value: 'viewer', label: 'Наблюдатель' },
          ]}
          value={role}
          onValueChange={setRole}
        />
        <JxSwitch
          label="Отправить уведомление по почте"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />
        <JxButton type="submit" variant="primary" disabled={!canSubmit}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

